db:update.db:input-parameters:
#[{
  invoiceId: vars.invoiceId,
  documentNumber: vars.erpResult.erpDocumentNumber,
  postedAt: ((vars.erpResult.postedAt as DateTime) >> "UTC") as String { format: "yyyy-MM-dd HH:mm:ss" }
}]

db:insert.db:input-parameters:
#[{
  invoiceId: vars.invoiceId,
  correlationId: correlationId,
  message: 'Posted to ERP as document ' ++ (vars.erpResult.erpDocumentNumber default ''),
  details: write({ erpStatus: vars.erpResult.erpStatus, fiscalYear: vars.erpResult.fiscalYear }, 'application/json', { indent: false })
}]
